-- clone_library_version(): copies a version (frozen or not) row-for-row into a new one,
-- keeps references inside the new version, and leaves the source untouched.

-- Per-table multiset difference between two versions, ignoring library_version and
-- evidence_method.id (regenerated by the clone). In the other tables 'id' is the natural key
-- and is compared. Returns the total number of differing rows.
CREATE FUNCTION pg_temp.version_diff(a INT, b INT) RETURNS BIGINT LANGUAGE plpgsql AS $f$
DECLARE
    tname TEXT;
    strip TEXT;
    n     BIGINT;
    total BIGINT := 0;
BEGIN
    FOREACH tname IN ARRAY ARRAY['control_family', 'requirement', 'assessment_objective',
                                 'check_rule', 'evidence_method'] LOOP
        strip := CASE WHEN tname = 'evidence_method' THEN $s$ - 'library_version' - 'id'$s$
                      ELSE $s$ - 'library_version'$s$ END;
        EXECUTE format($q$
            WITH x AS (SELECT to_jsonb(r)%2$s AS j FROM %1$I r WHERE library_version = $1),
                 y AS (SELECT to_jsonb(r)%2$s AS j FROM %1$I r WHERE library_version = $2)
            SELECT count(*) FROM ((SELECT j FROM x EXCEPT ALL SELECT j FROM y)
                                  UNION ALL (SELECT j FROM y EXCEPT ALL SELECT j FROM x)) d$q$, tname, strip)
        INTO n USING a, b;
        total := total + n;
    END LOOP;
    RETURN total;
END $f$;

