-- clone with no source: copies the newest version (1), which is frozen
CREATE TEMP TABLE v2 AS
SELECT clone_library_version(methodology => 'DoD Assessment Methodology v1.3', effective_date => '2027-01-01') AS id;

SELECT t_eq('a frozen version clones with every row identical',
            pg_temp.version_diff(1, (SELECT id FROM v2)), 0);
SELECT t_eq('all rows were copied (4 families, 4 requirements, 6 objectives, 2 rules, 3 methods)',
            (SELECT (SELECT count(*) FROM control_family WHERE library_version = v2.id) || ','
                 || (SELECT count(*) FROM requirement WHERE library_version = v2.id) || ','
                 || (SELECT count(*) FROM assessment_objective WHERE library_version = v2.id) || ','
                 || (SELECT count(*) FROM check_rule WHERE library_version = v2.id) || ','
                 || (SELECT count(*) FROM evidence_method WHERE library_version = v2.id) FROM v2),
            '4,4,6,2,3');
SELECT t_eq('the copy''s evidence methods use the copy''s rules',
            (SELECT count(*) FROM evidence_method m
             JOIN check_rule r ON r.library_version = m.library_version AND r.id = m.rule_id
             WHERE m.library_version = (SELECT id FROM v2)), 2);
SELECT t_eq('framework and revision come from the source; notes record where it came from',
            (SELECT framework || '|' || revision || '|' || methodology || '|' || effective_date || '|' || notes
             FROM library_version WHERE id = (SELECT id FROM v2)),
            'NIST SP 800-171|Rev 2|DoD Assessment Methodology v1.3|2027-01-01|Copied from library_version 1');

SELECT t_ok('the copy is editable',
    $$UPDATE requirement SET sprs_weight = 3 WHERE library_version = (SELECT id FROM v2) AND id = '3.5.3';
      UPDATE control_family SET name = 'Identification & Authentication'
          WHERE library_version = (SELECT id FROM v2) AND code = 'IA'$$);
SELECT t_eq('editing the copy leaves the source unchanged',
            (SELECT sprs_weight || '|' || (SELECT name FROM control_family WHERE library_version = 1 AND code = 'IA')
             FROM requirement WHERE library_version = 1 AND id = '3.5.3'),
            '5|Identification and Authentication');

CREATE TEMP TABLE v3 AS
SELECT clone_library_version(methodology => 'v1.3 draft B', effective_date => '2027-02-01') AS id;
SELECT t_eq('with no source given, the newest version (the edited copy) is cloned',
            pg_temp.version_diff((SELECT id FROM v2), (SELECT id FROM v3)), 0);
SELECT t_eq('... and so it differs from version 1 by the two edits (2 rows each side)',
            pg_temp.version_diff(1, (SELECT id FROM v3)), 4);

CREATE TEMP TABLE v4 AS
SELECT clone_library_version(methodology => 'CMMC 32 CFR 170.24 scoring', effective_date => '2026-11-10',
                             source_version => 1, framework => 'CMMC Level 2', revision => 'Rev 2 (CMMC)',
                             notes => 'scoring per 170.24') AS id;
SELECT t_eq('an explicit source is copied exactly', pg_temp.version_diff(1, (SELECT id FROM v4)), 0);
SELECT t_eq('framework, revision and notes can be overridden',
            (SELECT framework || '|' || revision || '|' || notes FROM library_version WHERE id = (SELECT id FROM v4)),
            'CMMC Level 2|Rev 2 (CMMC)|scoring per 170.24');

SELECT t_raises('a missing source is an error',
    $$SELECT clone_library_version(methodology => 'x', effective_date => '2027-01-01', source_version => 999)$$,
    'library_version 999 does not exist');

-- clone + failed edit in one transaction leaves nothing behind
CREATE TEMP TABLE before_count AS SELECT count(*) AS n FROM library_version;
BEGIN;
CREATE TEMP TABLE doomed AS
SELECT clone_library_version(methodology => 'doomed', effective_date => '2027-03-01') AS id;
SELECT t_raises('fixture: a bad edit to the new copy fails',
    $$UPDATE requirement SET sprs_weight = 2 WHERE library_version = (SELECT id FROM doomed) AND id = '3.5.3'$$,
    'requirement_check');
ROLLBACK;
SELECT t_eq('a rolled-back clone leaves no version behind',
            (SELECT count(*) FROM library_version), (SELECT n FROM before_count));

-- a column added to a library table later is copied too
ALTER TABLE requirement ADD COLUMN cmmc_id TEXT;
UPDATE requirement SET cmmc_id = 'IA.L2-3.5.3' WHERE library_version = (SELECT id FROM v4) AND id = '3.5.3';
CREATE TEMP TABLE v5 AS
SELECT clone_library_version(methodology => 'with CMMC ids', effective_date => '2027-04-01',
                             source_version => (SELECT id FROM v4)) AS id;
SELECT t_eq('a newly added column is copied',
            (SELECT cmmc_id FROM requirement WHERE library_version = (SELECT id FROM v5) AND id = '3.5.3'), 'IA.L2-3.5.3');
SELECT t_eq('... along with everything else', pg_temp.version_diff((SELECT id FROM v4), (SELECT id FROM v5)), 0);

-- the copies freeze independently
INSERT INTO assessment (id, org_id, library_version)
SELECT '10000000-0000-0000-0000-00000000000b', '00000000-0000-0000-0000-0000000000a1', id FROM v2;
UPDATE assessment SET status = 'signed', signed_by = 'CEO', signed_at = now()
WHERE id = '10000000-0000-0000-0000-00000000000b';
SELECT t_raises('signing on a copy freezes that copy',
    $$UPDATE requirement SET sprs_weight = 1 WHERE library_version = (SELECT id FROM v2) AND id = '3.1.1'$$, 'frozen');
SELECT t_ok('... but not the other copies',
    $$UPDATE requirement SET sprs_weight = 1 WHERE library_version = (SELECT id FROM v3) AND id = '3.1.1'$$);
SELECT t_ok('a frozen copy can itself be cloned',
    $$SELECT clone_library_version(methodology => 'from frozen v2', effective_date => '2027-05-01',
                                   source_version => (SELECT id FROM v2))$$);
